cd output && python3 - <<'EOF'
import docx
d = docx.Document("offer_letter_filled.docx")
texts=[]
def walk_tbl(t):
    for r in t.rows:
        for c in r.cells:
            for p in c.paragraphs: texts.append(p.text)
            for nt in c.tables: walk_tbl(nt)
for p in d.paragraphs: texts.append(p.text)
for t in d.tables: walk_tbl(t)
for s in d.sections:
    for part in (s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer):
        if part:
            for p in part.paragraphs: texts.append(p.text)
            for t in part.tables: walk_tbl(t)
full="\n".join(texts)
import re
left=re.findall(r"\{\{[^}]*\}\}", full)
print("LEFTOVERS:", left)
print("has RELOCATION_AMOUNT value 1,125:", "1,125" in full)
print("has Amélie:", "Amélie" in full)
print("has Ω:", "Ω" in full)
print("---- non-empty lines ----")
for t in texts:
    if t.strip(): print(repr(t))
EOF
